breach.segment:
// Ignore workloads that stopped reporting (deleted) more than 5 minutes before their cluster's newest sample
WHERE last_seen >= cluster_newest - 5 minutes
// Rollouts and scale-ups briefly drop ready below desired, so the workload must be short now and in every
// observed minute for at least 15 minutes. Keep observed_minutes below the rule window.
| WHERE shortfall >= 1 AND min_shortfall >= 1 AND observed_minutes >= 15
| KEEP resource.attributes.project_id, resource.attributes.location, resource.attributes.cluster,
       resource.attributes.namespace, kind, workload, desired, ready, shortfall, min_shortfall, observed_minutes
| SORT shortfall DESC
